+# Only unbound metadata and SQL layouts enter this cache. Red still creates
+# the AST/object and runs all of its create hooks and persistence bookkeeping.
+class CommandInsertCache {
+    has Lock $!lock .= new;
+    has %!descriptors;
+    has %!layouts;
+    has @!order;
+
+    method descriptor($model) {
+        $!lock.protect: {
+            %!descriptors{$model.WHICH.Str} //= $model.^columns.sort(*.column.name).map({
+                [ .column.name, so(.column.attr.type ~~ Json), .column ]
+            }).eager.List
+        }
+    }
+
+    method build-layout($driver, $model, @columns) {
+        my $table = $driver.table-name-wrapper($model.^table);
+        return "INSERT INTO $table DEFAULT VALUES RETURNING *" unless @columns;
+        my $pg = pg-driver($driver);
+        my @names = @columns.map({ $driver.table-name-wrapper($_[0]) });
+        my @placeholders = @columns.kv.map(-> $i, $column {
+            my $p = $pg ?? '$' ~ ($i + 1) !! '?';
+            $pg && $column[1] ?? "$p\::text::jsonb" !! $p
+        });
+        "INSERT INTO $table (" ~ @names.join(',') ~ ') VALUES ('
+            ~ @placeholders.join(',') ~ ') RETURNING *'
+    }
+
+    method layout($driver, $model, Str $key, Int $mask, $descriptor) {
+        $!lock.protect: {
+            if %!layouts{$key}:exists {
+                @!order = @!order.grep(* ne $key);
+                @!order.push($key);
+                return %!layouts{$key};
+            }
+            my @columns = $descriptor.kv.map(-> $i, $column { $column if $mask +& (1 +< $i) });
+            my $sql = self.build-layout($driver, $model, @columns);
+            @!order.push($key);
+            %!layouts{@!order.shift}:delete while @!order > 128;
+            %!layouts{$key} = $sql;
+        }
+    }
+}
+
+role CommandInsertPlans {
+    has CommandInsertCache $!command-insert-cache .= new;
+    method command-insert-plan(Red::AST::Insert $insert) {
+        my $model = $insert.into;
+        return Nil unless $model.^name eq 'RedSourcing::StoredCommand' && $model.^orig === $model;
+        my $descriptor = $!command-insert-cache.descriptor($model);
+        return Nil unless $insert.values.elems == $descriptor.elems;
+        my @arguments;
+        my Int $mask = 0;
+        for $descriptor.kv -> $i, $column {
+            my $value = $insert.values{$column[0]};
+            return Nil unless $value ~~ Red::AST::Value:D && $value.column === $column[2];
+            return Nil if $value.value ~~ Red::AST:D;
+            if $value.value.defined || ($column[1] && !($value.value === Json)) {
+                $mask +|= 1 +< $i;
+                @arguments.push($value);
+            }
+        }
+        my $key = $model.WHICH.Str ~ ':' ~ $mask;
+        my $sql = $!command-insert-cache.layout(self, $model, $key, $mask, $descriptor);
+        $sql => @arguments.map({ self.wildcard-value($_) }).Array
+    }
+}
+
+sub cached-command-insert($driver, Red::AST::Insert $insert, $context) is export {
+    return Nil if $context.defined || $driver !~~ CommandInsertPlans;
+    $driver.command-insert-plan($insert)
+}
