--- /dev/null
+++ b/t/66-command-insert-plans.rakutest
@@ -0,0 +1,153 @@
+use Test;
+use Red;
+use RedSourcing;
+use RedSourcing::Config;
+use RedSourcing::Storage;
+use Red::AST::Insert;
+use Red::AST::Value;
+use JSON::Fast;
+
+my $database = %*ENV<RED_SOURCING_TEST_PG_DATABASE>;
+my $schema = 'rs_insert_plans_' ~ $*PID;
+my $admin;
+my &new-driver;
+if $database {
+    require ::('DB::Pg');
+    $admin = ::('DB::Pg').new(:conninfo("dbname=$database"));
+    $admin.execute("CREATE SCHEMA $schema");
+    &new-driver = -> { store-driver('Pg', $database, :connection{
+        dbh => ::('DB::Pg').new(:conninfo("dbname=$database options='-csearch_path=$schema -cclient_min_messages=warning'"),
+            :converters(<DateTime UUID Geometric>))
+    }) };
+} else { &new-driver = -> { store-driver('SQLite', ':memory:') } }
+LEAVE $admin.execute("DROP SCHEMA $schema CASCADE") if $admin.defined;
+my $*RED-DB = new-driver();
+schema(StoredEvent, StoredCommand).create;
+my $layouts = 0;
+my $compiled = ::('RedSourcing::Storage::CommandInsertCache').^find_method('build-layout').wrap(-> |c {
+    $layouts++; callsame
+});
+LEAVE $compiled.restore;
+my %phases;
+my @notified;
+my $phasers = StoredCommand.HOW.^find_method('apply-row-phasers').wrap(-> |c {
+    my @args = c.list;
+    if @args[1].^name eq 'RedSourcing::StoredCommand' && @args[1].entity eq 'InsertTarget' {
+        %phases{@args[2].^name}++;
+    }
+    callsame
+});
+LEAVE $phasers.restore;
+my $notifications = StoredCommand.HOW.^find_method('emit').wrap(-> |c {
+    my @args = c.list;
+    @notified.push(@args[2]) if @args.elems >= 3 && @args[1].^name eq 'RedSourcing::StoredCommand' && @args[2] ~~ Red::AST::Insert;
+    callsame
+});
+LEAVE $notifications.restore;
+
+# Keep the reference row on a different layout so the measured layout starts cold.
+my $reference = StoredCommand.^create(:entity<InsertTarget>, :entity-ids{key => 0},
+    :method<perform>, :error<reference>, :stream<reference>, :next-run(DateTime.new('2026-01-01T00:00:00Z')),
+    :data{key => 0, values => [1, '1', True, Any]}, :parent-command-id(100), :action-id<cause-0>);
+$reference.entity-ids; $reference.data;
+my $reference-dirty = $reference.^is-dirty;
+
+$layouts = 0; %phases = (); @notified = ();
+
+my @rows;
+for ^3 -> $i {
+    my $time = DateTime.new('2026-01-01T00:00:00Z').later(:seconds($i));
+    my $row = StoredCommand.^create(:entity<InsertTarget>, :entity-ids{ key => $i },
+        :method<perform>, :stream("insert-$i"), :next-run($time),
+        :data{ key => $i, values => [1, '1', True, Any] },
+        :parent-command-id($i + 100), :action-id("cause-$i"));
+    @rows.push($row);
+    is $layouts, 1, 'same field set compiles SQL once';
+    ok $row.id.defined, 'database-generated ID is hydrated';
+    is $row.state, StoredCommand::Pending, 'default enum is preserved';
+    is $row.tries, 0, 'default attempt count is preserved';
+    is $row.next-run.Instant, $time.Instant, 'current timestamp is bound';
+    is-deeply $row.entity-ids, %(key => $i), 'identity payload is execution-local';
+    is-deeply $row.data, %(key => $i, values => [1, '1', True, Any]), 'JSON types survive insertion';
+    is $row.parent-command-id, $i + 100, 'parent metadata is execution-local';
+    is $row.action-id, "cause-$i", 'action metadata is execution-local';
+    ok $row.^is-on-db, 'created row is marked persisted';
+    is $row.^is-dirty, $reference-dirty, 'post-create dirty tracking remains consistent';
+}
+is @rows.map(*.id).unique.elems, 3, 'generated IDs are not cached';
+is @notified.elems, 3, 'Red emits one INSERT notification per create';
+is ([+] %phases.values), 6, 'BeforeCreate and AfterCreate remain active';
+is %phases.keys.grep(*.ends-with('BeforeCreate')).map({ %phases{$_} }).sum, 3, 'BeforeCreate runs each time';
+is %phases.keys.grep(*.ends-with('AfterCreate')).map({ %phases{$_} }).sum, 3, 'AfterCreate runs each time';
+is @notified[0].values{'stream'}.value, 'insert-0', 'first notification retains its AST values';
+is @notified[2].values{'stream'}.value, 'insert-2', 'later notification has current AST values';
+
+my $explicit = StoredCommand.^create(:id(50000), :entity<InsertTarget>, :entity-ids{},
+    :method<perform>, :stream<explicit>, :result{answer => [False, Any]}, :error<old>, :state(StoredCommand::Failed));
+is $explicit.id, 50000, 'explicit serial ID has its own insert shape';
+is $explicit.state, StoredCommand::Failed, 'non-default enum binds correctly';
+is-deeply $explicit.result, %(answer => [False, Any]), 'nullable JSON result preserves structured values';
+my $ast = Red::AST::Insert.new($explicit);
+my $cached = cached-command-insert($*RED-DB, $ast, Any);
+my $legacy = $*RED-DB.translate($ast, 'uncached-check');
+is $cached.key, $legacy.key, 'cached SQL matches the existing dialect translator';
+is-deeply $cached.value.Array, $legacy.value.Array, 'bind order matches the existing translator';
+ok !cached-command-insert($*RED-DB, $ast, 'other-context').defined, 'non-default contexts retain the original path';
+my %expr = $ast.values;
+%expr<result> = Red::AST::Value.new(:column($ast.values<result>.column), :value(ast-value(1)));
+ok !cached-command-insert($*RED-DB, Red::AST::Insert.new(:into(StoredCommand), :values(%expr)), Any).defined,
+    'expression values retain the original path';
+my $event = StoredEvent.new(:class<X>, :mro<|X|>, :stream<x>, :version(1), :data{});
+ok !cached-command-insert($*RED-DB, Red::AST::Insert.new($event), Any).defined, 'event INSERTs retain the original path';
+
+my $null-json = StoredCommand.^create(:entity<InsertTarget>, :entity-ids{},
+    :method<perform>, :stream<json-null>, :data(Any));
+my $sql-null = StoredCommand.^create(:entity<InsertTarget>, :entity-ids{},
+    :method<perform>, :stream<sql-null>);
+my @nulls = storage-query($*RED-DB,
+    q[SELECT stream, CASE WHEN data IS NULL THEN 1 ELSE 0 END AS missing FROM red_sourcing_command WHERE stream IN ('json-null','sql-null') ORDER BY stream]);
+is @nulls[0]<missing>, 0, 'undefined JSON payload is stored as JSON null';
+is @nulls[1]<missing>, 1, 'omitted JSON payload remains SQL NULL';
+
+my $before = StoredCommand.^all.elems;
+dies-ok { StoredCommand.^create(:id(50000), :entity<InsertTarget>, :entity-ids{}, :method<perform>, :stream<duplicate>) },
+    'duplicate INSERT errors propagate';
+is StoredCommand.^all.elems, $before, 'failed INSERT leaves no extra row';
+dies-ok {
+    red-do :transaction, {
+        StoredCommand.^create(:entity<InsertTarget>, :entity-ids{}, :method<perform>, :stream<rolled-back>);
+        die 'rollback';
+    }
+}, 'rollback works with a warm insert layout';
+is StoredCommand.^all.elems, $before, 'rolled-back values are not retained';
+
+# Synthetic AST shapes exercise the layout cache without inserting invalid rows.
+my $fresh-driver = new-driver();
+my $model = StoredCommand.new(:entity<X>, :entity-ids{});
+my $seed = Red::AST::Insert.new($model);
+my @names = $seed.values.keys.sort;
+sub shape(UInt $mask) {
+    Red::AST::Insert.new(:into(StoredCommand), :values(@names.kv.map(-> $i, $name {
+        my $column = $seed.values{$name}.column;
+        $name => Red::AST::Value.new(:$column, :value(($mask +& (1 +< $i)) ?? 1 !! $column.attr.type))
+    }).Hash))
+}
+my $start = $layouts;
+my $empty = cached-command-insert($fresh-driver, shape(0), Any);
+ok $empty.key.ends-with('DEFAULT VALUES RETURNING *'), 'empty format preserves DEFAULT VALUES';
+for 1..128 -> $mask { cached-command-insert($fresh-driver, shape($mask), Any) }
+is $layouts - $start, 129, 'different masks build independent layouts';
+cached-command-insert($fresh-driver, shape(0), Any);
+is $layouts - $start, 130, 'least recently used layout is evicted at 128 entries';
+my $clone = $fresh-driver.clone;
+cached-command-insert($clone, shape(0), Any);
+is $layouts - $start, 130, 'transaction clones share immutable SQL layouts';
+my @jobs = (^24).map(-> $i {
+    start {
+        my $ast = Red::AST::Insert.new(StoredCommand.new(:entity<InsertTarget>,
+            :entity-ids{key => $i}, :stream("parallel-$i")));
+        cached-command-insert($fresh-driver, $ast, Any).value.grep(* eq "parallel-$i").elems == 1
+    }
+});
+ok (await @jobs).all, 'concurrent bindings retain their own stream values';
+done-testing;
